#!/bin/sh
set -eu
export XDG_RUNTIME_DIR=/run/user/$(id -u)
while IFS='=' read -r name value; do
  case "$name" in
    DISPLAY|XAUTHORITY|DBUS_SESSION_BUS_ADDRESS|XDG_CURRENT_DESKTOP|XDG_SESSION_DESKTOP|XDG_SESSION_TYPE) export "$name=$value" ;;
    *) exit 1 ;;
  esac
done < "$XDG_RUNTIME_DIR/gbot/desktop.env"
export GTK_MODULES=atk-bridge QT_ACCESSIBILITY=1 NO_AT_BRIDGE=0
exec "$@"
